	using namespace noarr;

	num_t fn = static_cast<num_t>(n);

	// Initialize x, y, b
	// for (i = 0; i < n; i++) {
	//   x[i] = 0;
	//   y[i] = 0;
	//   b[i] = (i+1)/fn/2.0 + 4;
	// }
