		auto i = get_index<'i'>(state);

		x[state] = num_t(0);
		y[state] = num_t(0);

		x[state]; // keep structure usage symmetrical
		y[state];

		b[state] = (static_cast<num_t>(i + 1) / fn / num_t(2.0)) + num_t(4);
	});

	// Initialize A:
	// for (i = 0; i < n; i++) {
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	// }
	// Rewritten as a single 2D traversal with case distinction on j vs i.
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			// (DATA_TYPE)(-j % n) / n + 1;
			int nn = n;
			int jj = static_cast<int>(j);
			int rem = (-jj) % nn;
			A[state] = static_cast<num_t>(rem) / fn + num_t(1);
		} else if (j == i) {
			A[state] = num_t(1);
		} else {
			A[state] = num_t(0);
		}
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = 0
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	// A[r][s] = B[r][s]
	//
	// We keep the mathematical operation B = A * A^T, but implement it as
	// a per-(r,s) dot product over t. This
	//   - eliminates the explicit zeroing of B (each cell is written once),
	//   - and avoids repeatedly read-modify-writing B[r,s] N times.
	// This improves memory efficiency for B while preserving exact semantics
	// up to floating‑point rounding order.

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

