				auto rs_state = trav_rs.state();
				num_t acc = num_t(0);

				trav_rs.template for_each<'t'>([&](auto state) {
					acc += A_rt[state] * A_st[state];
				});

				B_rs[rs_state] = acc;
			});
		});

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
