// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Length in the 'i' dimension (matrix order)
	std::size_t n = A | get_length<'i'>();

	// LU factorization (Doolittle-like scheme)
	//
	// Original:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// Here we keep the same computation, but:
	//   - outer loops over (i,j) are expressed via a traverser
	//   - the inner reduction over k is also expressed via a 1D traverser
	//     over an auxiliary domain 'k'. This keeps all loop nests in the
	//     Noarr abstraction, and still compiles down to simple for-loops.

	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		trav_i.template for_each<'j'>([&](auto state) {
			auto j_idx = get_index<'j'>(state);

			num_t w = A[state];

			std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			// Reduction over k: w -= sum_{k=0..max_k-1} A[i,k] * A[k,j]
			traverser(k_domain_proto)
				.order(set_length<'k'>(max_k))
				.for_each([&](auto k_state) {
					auto k_idx = get_index<'k'>(k_state);

					w -= A.template at<'i', 'j'>(i_idx, k_idx) *
					     A.template at<'i', 'j'>(k_idx, j_idx);
				});

			if (j_idx < i_idx) {
				A[state] = w / A.template at<'i', 'j'>(j_idx, j_idx);
			} else {
				A[state] = w;
			}
		});
	});

	// Forward substitution: solve Ly = b
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }

	traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b[s_i];

		trav_i.template for_each<'j'>([&](auto state) {
			auto j_idx = get_index<'j'>(state);
			if (j_idx < i_idx) {
				w -= A.template at<'i', 'j'>(i_idx, j_idx) *
				     y.template at<'i'>(j_idx);
			}
		});

		y[s_i] = w;
	});

	// Backward substitution: solve Ux = y
	//
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// Implemented with an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv

	traverser(x, y, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_inv = trav_i.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv;

		num_t w = y.template at<'i'>(i_idx);

		trav_i.template for_each<'j'>([&](auto state) {
			auto j_idx = get_index<'j'>(state);
			if (j_idx > i_idx) {
				w -= A.template at<'i', 'j'>(i_idx, j_idx) *
				     x.template at<'i'>(j_idx);
			}
		});

		x.template at<'i'>(i_idx) =
			w / A.template at<'i', 'j'>(i_idx, i_idx);
	});
}

