// Main computational kernel
//
// This version keeps the original LU / forward / backward algorithms,
// but rewrites all inner loops in terms of Noarr traversers and adds a
// few layout‑aware views to improve data locality:
//
//  - LU dot products are expressed as 1D traversals over a synthetic
//    'k' dimension using two views:
//
//        A_ik: A[i,k]  (row i as a vector in k)
//        A_kj: A[k,j]  (column j as a vector in k)
//
//    so that for each (i,j) we compute
//
//        sum_k A[i,k] * A[k,j]
//
//    by traversing (A_ik_row, A_kj_col) over k.
//
//  - Triangular solves use noarr::slice on the 'j' dimension instead of
//    an explicit if(j < i) / if(j > i) inside the inner loop.
//
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Matrix order (length in the row dimension)
	std::size_t n = A | get_length<'i'>();

	// Views used to express LU dot products along a synthetic 'k' dimension:
	//   A_ik[i,k] = A[i,k]  (row-wise view: rename j -> k)
	//   A_kj[k,j] = A[k,j]  (column-wise view: rename i -> k)
	//
	// These do not change the physical layout, only the index names.
	auto A_ref = A.get_ref();
	auto A_ik = A_ref ^ noarr::rename<'j', 'k'>(); // dims: 'i','k'
	auto A_kj = A_ref ^ noarr::rename<'i', 'k'>(); // dims: 'k','j'

	// ------------------------------------------------------------------
	// 1. LU factorization (Doolittle, in-place)
	// ------------------------------------------------------------------
	//
	// Classical form for each row i:
	//   Lower (j < i):
	//     A[i,j] = (A[i,j] - sum_{k=0..j-1} A[i,k]*A[k,j]) / A[j,j]
	//   Upper (j >= i):
	//     A[i,j] =  A[i,j] - sum_{k=0..i-1} A[i,k]*A[k,j]
	//
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// Fix row view A[i,k] once per row: 1D vector over 'k'.
		auto A_ik_row = A_ik ^ noarr::fix<'i'>(i_idx);

		// 1.1 Strictly lower-triangular part: j in [0, i)
		//     (only present for i > 0)
		if (i_idx > 0) {
			trav_i
				// Restrict the 'j' dimension to [0, i)
				.order(noarr::slice<'j'>(0, i_idx))
				.for_each([&](auto s_ij) {
					std::size_t j_idx = get_index<'j'>(s_ij);

					num_t w = A[s_ij];

					// Dot product over k in [0, j_idx):
					//   sum_{k=0..j-1} A[i,k] * A[k,j]
					if (j_idx > 0) {
						// View of the k-th column at this j: A[k,j]
						auto A_kj_col = A_kj ^ noarr::fix<'j'>(j_idx);

						traverser(A_ik_row, A_kj_col)
							.order(noarr::slice<'k'>(0, j_idx))
							.for_each([&](auto s_k) {
								w -= A_ik_row[s_k] * A_kj_col[s_k];
							});
					}

					// Divide by the diagonal pivot A[j,j]
					auto diag_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
					A[s_ij] = w / A[diag_state];
				});
		}

		// 1.2 Upper-triangular part including diagonal: j in [i, n)
		trav_i
			// Restrict 'j' to [i, n)
			.order(noarr::slice<'j'>(i_idx, n - i_idx))
			.for_each([&](auto s_ij) {
				std::size_t j_idx = get_index<'j'>(s_ij);

				num_t w = A[s_ij];

				// Dot product over k in [0, i_idx):
				//   sum_{k=0..i-1} A[i,k] * A[k,j]
				if (i_idx > 0) {
					auto A_kj_col = A_kj ^ noarr::fix<'j'>(j_idx);

					traverser(A_ik_row, A_kj_col)
						.order(noarr::slice<'k'>(0, i_idx))
						.for_each([&](auto s_k) {
							w -= A_ik_row[s_k] * A_kj_col[s_k];
						});
				}

				A[s_ij] = w;
			});
	});

	// ------------------------------------------------------------------
	// 2. Forward substitution: solve L y = b
	//
	//   for i = 0..N-1:
	//     y[i] = b[i] - sum_{j=0..i-1} A[i,j] * y[j]
	//
	// L has unit diagonal and is stored in the strict lower part of A.
	// ------------------------------------------------------------------
	traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b[s_i];

		if (i_idx > 0) {
			// Restrict 'j' to [0, i)
			trav_i
				.order(noarr::slice<'j'>(0, i_idx))
				.for_each([&](auto s_ij) {
					std::size_t j_idx = get_index<'j'>(s_ij);

					auto y_j_state = noarr::idx<'i'>(j_idx);
					auto A_ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

					w -= A[A_ij_state] * y[y_j_state];
				});
		}

		y[s_i] = w;
	});

	// ------------------------------------------------------------------
	// 3. Backward substitution: solve U x = y
	//
	//   for i = N-1..0:
	//     x[i] = ( y[i] - sum_{j=i+1..N-1} A[i,j] * x[j] ) / A[i,i]
	//
	// Implemented with an ascending "inverse" index inv = 0..N-1:
	//   i = N-1 - inv
	// so that the outer loop can still use traverser over 'i'.
	// ------------------------------------------------------------------
	traverser(x, y, A).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv;

		auto row_state = noarr::idx<'i'>(i_idx);
		num_t w = y[row_state];

		if (i_idx + 1 < n) {
			std::size_t len = n - (i_idx + 1);

			// Restrict 'j' to (i, N) = [i+1, N)
			trav_inv
				.order(noarr::slice<'j'>(i_idx + 1, len))
				.for_each([&](auto s_j) {
					std::size_t j_idx = get_index<'j'>(s_j);

					auto A_ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);
					auto x_j_state = noarr::idx<'i'>(j_idx);

					w -= A[A_ij_state] * x[x_j_state];
				});
		}

		auto diag_state = noarr::idx<'i', 'j'>(i_idx, i_idx);
		x[row_state] = w / A[diag_state];
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
