				num_t w = A[state];

				// w -= sum_{k=0..j_idx-1} A[i_idx,k] * A[k,j_idx]
				for (std::size_t k = 0; k < j_idx; ++k) {
					w -= A.template at<'i', 'j'>(i_idx, k) *
					     A.template at<'i', 'j'>(k, j_idx);
				}

				A[state] = w / A.template at<'i', 'j'>(j_idx, j_idx);
			});
		}

		// ----- U-part: diagonal and upper, j in [i_idx, n) -----
		{
			std::size_t len_u = n - i_idx;
			auto trav_U = trav_i.order(noarr::slice<'j'>(i_idx, len_u));

			trav_U.for_each([&](auto state) {
				std::size_t j_idx = get_index<'j'>(state);

				num_t w = A[state];

				// w -= sum_{k=0..i_idx-1} A[i_idx,k] * A[k,j_idx]
				for (std::size_t k = 0; k < i_idx; ++k) {
					w -= A.template at<'i', 'j'>(i_idx, k) *
					     A.template at<'i', 'j'>(k, j_idx);
				}

				A[state] = w;
			});
		}
	});

