	// Backward substitution: solve Ux = y
	//
	//   for (i = N-1; i >= 0; i--) {
	//     w = y[i];
	//     for (j = i+1; j < N; j++)
	//       w -= A[i][j] * x[j];
	//     x[i] = w / A[i][i];
	//   }
	//
	// Implemented as an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	//
	// As above, we use a slice over 'j' instead of a branch on j>i.
	// ------------------------------------------------------------------
	traverser(x, y, A).template for_dims<'i'>([&](auto trav_inv) {
